// Code Playground: Land Cost Calculator (Simulasi) 
// Aturan ringkas: total = purchasePrice + closingCosts + sitePrep + assumedEncumbrances + indefiniteImprovements + specialAssessments - salvageProceeds 

const purchasePrice = 50000000; // contoh: ¥ 50,000,000
const closingCosts = 2000000;  // contoh: title/attorney/recording fees
const sitePrep = 3500000;      // contoh: grading, filling, draining, clearing
const assumedEncumbrances = 15000000; // back taxes + liens + mortgages assumed
const indefiniteImprovements = 1200000; // perbaikan dengan life tidak terbatas
const specialAssessments = 800000; // street lights, sewers, drainage, dll
const salvageProceeds = 300000; // proceeds dari material demolition/cleared timber (mengurangi cost)

const totalLandCost = purchasePrice + closingCosts + sitePrep + assumedEncumbrances + indefiniteImprovements + specialAssessments - salvageProceeds;

console.log("Total land cost (simulasi):", totalLandCost);

// Challenge: Ubah angka-angka di atas untuk mencocokkan kasus tugasmu.

// Code Playground: PPE vs Expense (Rules Mini)
// Sederhana untuk latihan logika klasifikasi.

function classifyCost(costType) {
  const PPE = ["purchase", "import_duty", "non_refundable_tax", "delivery", "site_prep", "setup_to_use", "capitalized_repairs_ready_to_use", "closing_costs", "assumed_liens_mortgages"];
  const EXPENSE = ["ordinary_repairs", "routine_maintenance", "current_period_service_only"];

  if (PPE.includes(costType)) return "PPE (capitalize)";
  if (EXPENSE.includes(costType)) return "Expense";
  return "Unknown";
}

const test = ["purchase", "delivery", "ordinary_repairs", "site_prep", "routine_maintenance", "setup_to_use"];

for (const t of test) {
  console.log(t, "=>", classifyCost(t));
}

